mapper.select:
select 
from (
    select 
    from APP_TERMINATION_REQUEST
    where TERMINATION_STATUS = #{status,jdbcType=VARCHAR}
    order by REQUEST_TIME
)
where ROWNUM <= #{limit,jdbcType=INTEGER}

select 
from (
    select 
    from APP_TERMINATION_REQUEST
    where TERMINATION_STATUS = #{status,jdbcType=VARCHAR}
      and REQUEST_TIME <= #{cutoff,jdbcType=TIMESTAMP}
    order by REQUEST_TIME
)
where ROWNUM <= #{limit,jdbcType=INTEGER}

select 
from (
    select 
    from APP_TERMINATION_REQUEST
    where NVL(NOTIFY_RETRY_COUNT, 0) < #{maxRetryCount,jdbcType=INTEGER}
      and TERMINATION_STATUS in ('SUCCESS', 'FAILED')
      and (
            NOTIFY_STATUS = 'FAILED'
         or (NOTIFY_STATUS = 'PENDING'
             and NVL(NOTIFY_TIME, CREATE_TIME)
                 < SYSTIMESTAMP - NUMTODSINTERVAL(#{staleMinutes,jdbcType=INTEGER}, 'MINUTE'))
      )
    order by NVL(NOTIFY_TIME, CREATE_TIME)
)
where ROWNUM <= #{limit,jdbcType=INTEGER}

select TERMINATION_STATUS
from APP_TERMINATION_REQUEST
where REQUEST_SIGN_SEQ = #{requestSignSeq,jdbcType=VARCHAR}

select 
from (
    select 
    from APP_TERMINATION_REQUEST
    where NVL(CHANNEL_SYNC_RETRY_COUNT, 0) < #{maxRetryCount,jdbcType=INTEGER}
      and TERMINATION_STATUS = 'SUCCESS'
      and (
            CHANNEL_SYNC_STATUS = 'FAILED'
         or (CHANNEL_SYNC_STATUS = 'PENDING'
             and NVL(CHANNEL_SYNC_TIME, CREATE_TIME)
                 < SYSTIMESTAMP - NUMTODSINTERVAL(#{staleMinutes,jdbcType=INTEGER}, 'MINUTE'))
      )
    order by NVL(CHANNEL_SYNC_TIME, CREATE_TIME)
)
where ROWNUM <= #{limit,jdbcType=INTEGER}
